const CACHE = `menstruapp-${VERSION}`;
const DB_NAME = 'menstruapp';

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      await cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' })));
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k.startsWith('menstruapp-') && k !== CACHE).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith('/api/')) return;
  const isDocument = req.mode === 'navigate' && (!/\.[a-z0-9]+$/i.test(url.pathname) || url.pathname.endsWith('.html'));
  event.respondWith(isDocument ? handleNavigation(req, url) : cacheFirst(req));
});

/** @param {Request} req @param {URL} url */
async function handleNavigation(req, url) {
  const cache = await caches.open(CACHE);
  const page = url.pathname === '/share.html' ? '/share.html' : '/index.html';
  const cached = await cache.match(page);
  if (cached) return cached;
  try {
    return await fetch(req);
  } catch {
    return (await cache.match('/index.html')) || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
  }
}

/** @param {Request} req */
async function cacheFirst(req) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(req, { ignoreSearch: true });
  if (cached) return cached;
  const res = await fetch(req);
  if (res.ok && res.type === 'basic') cache.put(req, res.clone());
  return res;
}

// --- IndexedDB helpers (read-only; never create the database from the worker) ---------------

function openDb() {
  return new Promise((resolve) => {
    const request = indexedDB.open(DB_NAME);
    request.onupgradeneeded = () => {
      // The database does not exist yet: abort instead of creating an empty one.
      request.transaction.abort();
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => resolve(null);
  });
}

/** @param {IDBDatabase} db @param {string} store @param {IDBValidKey} key */
function idbGet(db, store, key) {
  return new Promise((resolve) => {
    try {
      const r = db.transaction(store, 'readonly').objectStore(store).get(key);
      r.onsuccess = () => resolve(r.result);
      r.onerror = () => resolve(undefined);
    } catch {
      resolve(undefined);
    }
  });
}

/** @param {IDBDatabase} db @param {string} store */
function idbAll(db, store) {
  return new Promise((resolve) => {
    try {
      const r = db.transaction(store, 'readonly').objectStore(store).getAll();
      r.onsuccess = () => resolve(r.result || []);
      r.onerror = () => resolve([]);
    } catch {
      resolve([]);
    }
  });
}

/** @param {IDBDatabase} db @param {string} store @param {any} value @param {IDBValidKey} key */
function idbPut(db, store, value, key) {
  return new Promise((resolve) => {
    try {
      const tx = db.transaction(store, 'readwrite');
      tx.objectStore(store).put(value, key);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    } catch {
      resolve(false);
    }
  });
}

/** @param {string} b64 */
function fromB64(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** @param {CryptoKey} key @param {{ iv: string, ct: string }} payload */
async function decrypt(key, payload) {
  const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: fromB64(payload.iv) }, key, fromB64(payload.ct));
  return JSON.parse(new TextDecoder().decode(plain));
}

const ICON = '/assets/icons/icon-192.png';
const BADGE = '/assets/icons/badge-96.png';

/** @param {string} title @param {string} body @param {string} tag */
function show(title, body, tag) {
  return self.registration.showNotification(title, { body, tag, icon: ICON, badge: BADGE, data: { url: '/#/home' } });
}

self.addEventListener('push', (event) => {
  event.waitUntil(
    (async () => {
      let title = 'Menstruapp';
      let body = '🔔';
      let tag = 'menstruapp';
      try {
        const data = event.data ? event.data.json() : null;
        const db = await openDb();
        const key = db ? await idbGet(db, 'meta', 'notifKey') : null;
        if (data && key) {
          const plain = await decrypt(key, data);
          title = String(plain.title || title).slice(0, 80);
          body = String(plain.body || '').slice(0, 240);
          tag = String(plain.tag || tag).slice(0, 80);
          const shown = (await idbGet(db, 'meta', 'notifShown')) || [];
          await idbPut(db, 'meta', [...shown, tag].slice(-300), 'notifShown');
        }
      } catch {
        /* show a neutral notification: every push must display something */
      }
      await show(title, body, tag);
    })(),
  );
});

self.addEventListener('periodicsync', (event) => {
  if (event.tag !== 'menstruapp-reminders') return;
  event.waitUntil(
    (async () => {
      const db = await openDb();
      if (!db) return;
      const key = await idbGet(db, 'meta', 'notifKey');
      if (!key) return;
      const now = new Date();
      const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
      const shown = (await idbGet(db, 'meta', 'notifShown')) || [];
      const rows = await idbAll(db, 'notifications');
      const fresh = [];
      for (const row of rows) {
        if (!row.dateOnly || row.date !== today || row.at > now.getTime() || shown.includes(row.id)) continue;
        try {
          const plain = await decrypt(key, row.payload);
          await show(plain.title, plain.body, plain.tag || row.id);
          fresh.push(row.id);
        } catch {
          /* skip */
        }
      }
      if (fresh.length) await idbPut(db, 'meta', [...shown, ...fresh].slice(-300), 'notifShown');
    })(),
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = new URL((event.notification.data && event.notification.data.url) || '/', self.location.origin);
  if (target.origin !== self.location.origin) return;
  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      for (const client of windows) {
        if (new URL(client.url).origin === self.location.origin && 'focus' in client) return client.focus();
      }
      return self.clients.openWindow(target.href);
    })(),
  );
});
